    # If no such non-negative solution exists, return None.
    # Otherwise return (x, y).
    # If a or b is zero, handle separately.

    if a == 0 and b == 0:
        # Only solution if n == 0, then x=y=0 else no solution
        if n == 0:
            return (0, 0)
        else:
            return None

    if a == 0:
        # Then b*y = n, y = n/b if integer and non-negative
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        # Then a*x = n, x = n/a if integer and non-negative
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    from math import gcd
    d = gcd(a, b)
    if n % d != 0:
        # No integer solutions at all
        return None

    # Use extended Euclidean algorithm to find one solution (x0, y0) to a*x + b*y = d
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        d, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return (d, x, y)

    _, x0, y0 = extended_gcd(a, b)
    # Scale the solution to n
    x0 *= n // d
    y0 *= n // d

    # General solution:
    # x = x0 + k*(b/d)
    # y = y0 - k*(a/d)
    # We want x >= 0 and y >= 0.
    # Find k range satisfying both constraints:
    # x0 + k*(b/d) >= 0  => k >= -x0/(b/d)
    # y0 - k*(a/d) >= 0  => k <= y0/(a/d)

    bd = b // d
    ad = a // d

    # Compute lower bound for k
    import math
    k_min = math.ceil(-x0 / bd) if bd != 0 else float('-inf')
    k_max = math.floor(y0 / ad) if ad != 0 else float('inf')

    if k_min > k_max:
        # No k satisfies both
        return None

    # Any k in [k_min, k_max] works, pick k = k_min (smallest k)
    k = k_min
    x = x0 + k * bd
    y = y0 - k * ad

    if x >= 0 and y >= 0:
        return (x, y)
