        return None  # or raise an error depending on assumptions

    left, right = 0, len(arr) - 1

    # If array is not rotated (sorted ascending), last element is max
    if arr[left] < arr[right]:
        return arr[right]

    while left <= right:
        mid = (left + right) // 2

        # Check if mid is max
        if mid < right and arr[mid] > arr[mid + 1]:
            return arr[mid]
        if mid > left and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]

        # Decide which half to go
        if arr[mid] >= arr[left]:
            # Left half is sorted, max must be in right half
            left = mid + 1
        else:
            # Right half is sorted, max must be in left half
            right = mid - 1

    # Fallback
    return arr[0]

