def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Helper to check if all digits are '9'
    if all(ch == '9' for ch in s):
        # For all 9's, next palindrome greater than num is 10...01 (length+1 digits)
        return num + 2  # e.g. 9->11, 99->101, 999->1001

    def mirror_left_to_right(left: str, length: int) -> str:
        if length % 2 == 0:
            return left + left[::-1]
        else:
            return left + left[-2::-1]

    # Increment a numeric string by 1 (used for the left half)
    def increment_str_num(num_str: str) -> str:
        num = int(num_str) + 1
        return str(num)

    # Split into left half (plus middle if odd)
    if length % 2 == 0:
        left = s[:length//2]
        middle = ''
        right = s[length//2:]
    else:
        left = s[:length//2+1]
        middle = ''
        right = s[length//2+1:]

    # Form a palindrome by mirroring left half
    p = mirror_left_to_right(left, length)
    p_int = int(p)
    if p_int > num:
        return p_int

    # Need to increment the left half and mirror again
    # For odd length, left includes the middle digit
    incremented_left = increment_str_num(left)

    # If length changes after increment (e.g. 999 +1 = 1000), handle specially
    if len(incremented_left) > len(left):
        # This means palindrome length increases by 1
        # Example: 999 -> incremented_left=1000, length=3 -> 4 digit palindrome
        # The next palindrome is 10...01 with length+1 digits
        return int("1" + ("0"*(length-1)) + "1")

    p2 = mirror_left_to_right(incremented_left, length)
    return int(p2)

