def get_total_number_of_sequences(m: int, n: int) -> int:
    # Count nondecreasing sequences of length n from [1..m]
    # with no repeated elements and for each consecutive pair (a[i], a[i+1]),
    # a[i+1] >= 2*a[i].
    # Because repeated elements are not allowed, and the sequence is nondecreasing,
    # conditions imply strictly increasing.

    from functools import lru_cache

    @lru_cache(None)
    def dfs(pos: int, prev: int) -> int:
        if pos == n:
            return 1
        count = 0
        start = max(prev * 2, prev + 1) if prev != 0 else 1
        # prev=0 means no previous element chosen yet
        # For pos=0, prev=0, start=1
        for next_val in range(start, m + 1):
            count += dfs(pos + 1, next_val)
        return count

    return dfs(0, 0)

