def text_match_two_three(s: str) -> bool:
    # Matches a substring with one letter followed by 1 to 3 repetitions of another letter (different from the first)
    # e.g. 'ab', 'abb', 'abbb', but not 'aaa' (since repetition must be a different letter)
    pattern = r'([a-zA-Z])([a-zA-Z])\2{0,2}'
