from collections.abc import Iterable

def remove_column(data, pos):
    if isinstance(data, dict):
        # For dicts, process values recursively
        return {k: remove_column(v, pos) for k, v in data.items()}
    if isinstance(data, str):
        # Strings are iterable but should be treated as atomic, return as is
        return data
    if isinstance(data, Iterable):
        # For iterables (lists, tuples, sets, etc.), process elements
        # First, process elements recursively
        processed = [remove_column(elem, pos) for elem in data]
        # Then remove element at position pos if possible
        # If processed is not indexable (e.g. set), convert to list first
        # We'll produce result in same type as input, except sets become list (to preserve order)
        try:
            # Try to remove element at pos
            # If pos is out of range, just return processed as is
            if 0 <= pos < len(processed):
                del processed[pos]
        except TypeError:
            # len() or indexing not supported, just return processed as is
            pass
        # Rebuild in same type if possible
        if isinstance(data, list):
            return processed
        elif isinstance(data, tuple):
            return tuple(processed)
        elif isinstance(data, set):
            # Sets are unordered, removing by position is ambiguous,
            # but per task, remove element at position in iteration order
            return set(processed)
        else:
            # For other iterables, try to return same type if possible
            try:
                return type(data)(processed)
            except Exception:
                return processed
    # For non-iterables, return as is
    return data

