def compute_Last_Digit(a: int, b: int) -> int:
    # We want the last digit of (b! / a!) = (a+1) * (a+2) * ... * b
    # If a == b, the result is 1, last digit 1.
    if a == b:
        return 1
    product = 1
    for x in range(a + 1, b + 1):
        product = (product * x) % 10
        # If product ends with 0, it will stay 0, so can break early
        if product == 0:
            break
    return product

