def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    def is_all_nines(s):
        return all(ch == '9' for ch in s)

    if is_all_nines(s):
        # For all 9's, next palindrome is 10...01 (length+1)
        return int("1" + ("0" * (length - 1)) + "1")

    # Helper to create palindrome by mirroring left to right
    def make_palindrome(left, odd_length):
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    odd_length = (length % 2 != 0)
    left_half_len = (length + 1) // 2
    left = s[:left_half_len]

    # Generate palindrome by mirroring left
    pal = int(make_palindrome(left, odd_length))

    if pal > num:
        return pal

    # Need to increment the middle part (left half + middle if odd)
    # Convert left to int, increment by 1, then form palindrome again
    left_int = int(left) + 1
    left_str = str(left_int)

    # If increment caused length increase (e.g. 999 -> 1000)
    if len(left_str) > left_half_len:
        # This means palindrome length will increase, e.g. 999 -> 1001
        # So the next palindrome is '1' + '0'*(length-1) + '1'
        return int("1" + ("0" * (length - 1)) + "1")

    return int(make_palindrome(left_str, odd_length))

