def find_solution(a, b, n):
    if b == 0:
        # If b=0, equation is a*x = n
        if a == 0:
            return (0, 0) if n == 0 else None
        if n % a == 0:
            return (n // a, 0)
        return None

    x = 0
    while True:
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            return (x, y)
        x += 1
        # To avoid infinite loop, stop if x gets too large
        # since x is nonnegative, if a > 0 and n < 0, no solution for large x
        # or if a == 0, we already handled
        # So a reasonable upper bound:
        if x > abs(n) + abs(b):
            break
    return None

